class Character{constructor(t){if(!t)throw new Error("Character config is required");this.level=t.level,this.mode=t.mode,this.race=t.race,this.logging=t.logging,this.target=t.target,this.timer=0,this.itemtimer=0,this.crittimer=0,this.critdmgbonus=0,this.extraattacks=0,this.batchedextras=0,this.spelldamage=0,this.mainspelldmg=1,this.base={ap:0,agi:0,str:0,int:0,spi:0,sta:0,arp:0,hit:0,crit:0,spellcrit:0,spellhit:0,spelldamage:0,mp5:0,skill_0:5*this.level,skill_1:5*this.level,skill_2:5*this.level,skill_3:5*this.level,skill_4:5*this.level,skill_5:5*this.level,skill_6:5*this.level,skill_7:this.level<35?225:300,skill_10:0,skill_11:0,skill_13:0,skill_20:0,skill_21:0,skill_23:0,haste:1,expertise:0,strmod:1,agimod:1,intmod:1,spimod:1,dmgmod:1,spelldmgmod:1,moddmgdone:0,moddmgtaken:0,apmod:1,baseapmod:1,resist:{shadow:0,arcane:0,nature:0,fire:0,frost:0},block:0,defense:0},this.stats={},this.initializeClass(t)}initializeClass(t){throw new Error("initializeClass must be implemented by subclass")}getClassName(){throw new Error("getClassName must be implemented by subclass")}getResourceType(){throw new Error("getResourceType must be implemented by subclass")}steptimer(t){this.timer&&(this.timer=Math.max(0,this.timer-t))}stepitemtimer(t){this.itemtimer&&(this.itemtimer=Math.max(0,this.itemtimer-t))}log(t){this.logging&&this.combatlog&&this.combatlog.push(step+" "+t)}getArmorReduction(){let t=this.target.basearmor,s=this.target.level,e=(t=Math.max(0,t-(this.stats.arp||0)))/(t+400+85*s);return e=Math.max(0,Math.min(.75,e))}physproc(t){let s=0,e=rng10k();return e<(s+=100*Math.max(this.mh.miss,0))?0:e<(s+=100*this.mh.dodge)?0:((e=rng10k())<100*(this.crit+this.mh.crit)&&(t*=1+1*(1+2*this.critdmgbonus)),t*this.stats.dmgmod*this.mh.modifier*(1-this.armorReduction))}serializeStats(){return{class:this.getClassName(),level:this.level,race:this.race,stats:this.stats,base:this.base}}}